UPDATE "TemplateBuilderDocument" SET "publishedVersionId" = 'builder_seed_itinerary_v1', "updatedAt" = CURRENT_TIMESTAMP
WHERE "code" = 'CURRENT_ITINERARY' AND EXISTS (SELECT 1 FROM "TemplateBuilderVersion" WHERE "id" = 'builder_seed_itinerary_v1');
UPDATE "TemplateBuilderDocument" SET "publishedVersionId" = 'builder_seed_invoice_v1', "updatedAt" = CURRENT_TIMESTAMP
WHERE "code" = 'CURRENT_INVOICE' AND EXISTS (SELECT 1 FROM "TemplateBuilderVersion" WHERE "id" = 'builder_seed_invoice_v1');
UPDATE "TemplateBuilderDocument" SET "publishedVersionId" = 'builder_seed_estimate_v1', "updatedAt" = CURRENT_TIMESTAMP
WHERE "code" = 'CURRENT_ESTIMATE' AND EXISTS (SELECT 1 FROM "TemplateBuilderVersion" WHERE "id" = 'builder_seed_estimate_v1');
